WITH scored AS (SELECT *, SUM(monthly_fee) OVER (PARTITION BY customer_id ORDER BY monthly_fee, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) cumulative_monthly_fee, LAG(monthly_fee, 2) OVER (PARTITION BY DATE_TRUNC('month', end_date), plan ORDER BY end_date, id) prev_monthly_fee FROM subscriptions) SELECT s.id, s.customer_id, s.plan, s.start_date, s.monthly_fee, s.status, s.prev_monthly_fee, (SELECT MAX(t2.amount) FROM orders t2 WHERE t2.customer_id = s.customer_id) AS max_order_amount FROM scored s
